import threading
import queue
from concurrent.futures import ThreadPoolExecutor

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return 0

def render_body(body):
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))
    return re.sub(r'\{\{\s*([^}]+)\s*\}\}', replace_match, body)

def send_request(url, body):
    response = requests.post(url, json=body, headers={'Content-Type': 'application/json'})
    return {
        'url': url,
        'status': response.status_code,
        'body': response.text
    }

def worker(request_queue, result_queue, max_concurrent):
    while True:
        try:
            request = request_queue.get_nowait()
            result = send_request(request['url'], render_body(request['body']))
            result_queue.put(result)
        except queue.Empty:
            break

def batch_runner(config_path):
    with open(config_path) as f:
        config = json.load(f)

    request_queue = queue.Queue()
    result_queue = queue.Queue()
    threads = []

    for request in config['requests']:
        request_queue.put({
            'url': request['url'],
            'body': request['body']
        })

    for _ in range(config['max_concurrent']):
        t = threading.Thread(target=worker, args=(request_queue, result_queue, config['max_concurrent']))
        t.start()
        threads.append(t)

    for _ in range(config['max_concurrent']):
        request_queue.put(None)  # Signal threads to exit

    for t in threads:
        t.join()

    while not result_queue.empty():
        result = result_queue.get()
        print(json.dumps(result))

