import json
import requests
import threading
import queue
import re
from concurrent.futures import ThreadPoolExecutor, as_completed

def evaluate_expression(expr):
    # Replace spaces for easier parsing
    expr = expr.replace(' ', '')
    # Handle parentheses first
    stack = []
    i = 0
    while i < len(expr):
        if expr[i] == '(':
            stack.append(i)
        elif expr[i] == ')':
            start = stack.pop()
            sub_expr = expr[start+1:i]
            sub_result = evaluate_expression(sub_expr)
            expr = expr[:start] + str(sub_result) + expr[i+1:]
            i = start + len(str(sub_result))
        else:
            i += 1
    # Evaluate remaining expression
    tokens = re.findall(r'(\d+|\+|\-|\*)', expr)
    result = int(tokens[0])
    for i in range(1, len(tokens), 2):
        op = tokens[i]
        num = int(tokens[i+1])
        if op == '+':
            result += num
        elif op == '-':
            result -= num
        elif op == '*':
            result *= num
    return result

def process_request(request):
    url = request['url']
    body = request['body']
    # Replace all placeholders
    for match in re.finditer(r'\{\{(\d+[+\-*\d\(\)]*)\}\}', body):
        expr = match.group(1)
        try:
            value = evaluate_expression(expr)
            body = body.replace(match.group(0), str(value))
        except:
            body = body.replace(match.group(0), '0')  # Fallback to 0 if evaluation fails
    try:
        response = requests.post(url, json=body, headers={'Content-Type': 'application/json'})
        return {
            'url': url,
            'status': response.status_code,
            'body': response.text
        }
    except Exception as e:
        return {
            'url': url,
            'status': 0,
            'body': str(e)
        }

def batch_runner(config_path):
    with open(config_path, 'r') as f:
        config = json.load(f)

    max_concurrent = config['max_concurrent']
    requests_list = config['requests']

    results = []
    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = {executor.submit(process_request, req): req for req in requests_list}
        for future in as_completed(futures):
            result = future.result()
            results.append(result)

    for result in results:
        print(json.dumps(result))

if __name__ == "__main__":
