import json
import requests
import re
from concurrent.futures import ThreadPoolExecutor, as_completed
from typing import Dict, List, Any

def evaluate_expression(expr: str) -> int:
    # Replace {{ and }} with empty strings to isolate the expression
    expr = expr.strip('{}')
    # Use a simple evaluator for integer expressions with +, -, *, and parentheses
    def safe_eval(expr: str) -> int:
        try:
            return eval(expr, {'__builtins__': None}, {})
        except:
            raise ValueError(f"Invalid expression: {expr}")
    return safe_eval(expr)

def render_body(body: str, config: Dict[str, Any]) -> str:
    # Replace all {{expr}} placeholders with evaluated expressions
    def replace_placeholder(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))
    return re.sub(r'\{\{([^}]+)\}\}', replace_placeholder, body)

def process_request(request: Dict[str, Any], max_concurrent: int) -> None:
    url = request['url']
    body = render_body(request['body'], None)
    try:
        response = requests.post(url, json=body, headers={'Content-Type': 'application/json'})
        status = response.status_code
        result = {"url": url, "status": status, "body": response.text}
        print(json.dumps(result))
    except Exception as e:
        print(json.dumps({"url": url, "status": 500, "body": str(e)}), end='\n')

def main():
    import sys
    if len(sys.argv) != 2:
        print("Usage: python batch_runner.py CONFIG_PATH", file=sys.stderr)
        return

    config_path = sys.argv[1]
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except Exception as e:
        print(f"Error loading config: {e}", file=sys.stderr)
        return

    max_concurrent = config.get('max_concurrent', 1)
    requests_list = config.get('requests', [])

    with ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        futures = []
        for request in requests_list:
            futures.append(executor.submit(process_request, request, max_concurrent))

        for future in as_completed(futures):
            future.result()

if __name__ == "__main__":
    main()

import json
import requests
import re
import concurrent.futures
import sys

def evaluate_expression(expr):
    try:
        return int(eval(expr))
    except:
        return 0

def render_body(body):
    def replace_match(match):
        expr = match.group(1)
        return str(evaluate_expression(expr))

    return re.sub(r'\{\{([^}]+)\}\}', replace_match, body)

def process_request(config_item):
    url = config_item["url"]
    body = render_body(config_item["body"])
    headers = {"Content-Type": "application/json"}
    response = requests.post(url, json=body, headers=headers)
    return {
        "url": url,
        "status": response.status_code,
        "body": response.text
    }

def batch_runner(config_path):
    with open(config_path) as f:
        config = json.load(f)

    max_concurrent = config["max_concurrent"]
    requests_list = config["requests"]

    results = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=max_concurrent) as executor:
        future_to_request = {
            executor.submit(process_request, req): req for req in requests_list
        }
        for future in concurrent.futures.as_completed(future_to_request):
            req = future_to_request[future]
            try:
                result = future.result()
                results.append(result)
            except Exception as e:
                results.append({
                    "url": req["url"],
                    "status": 0,
                    "body": f"Error: {str(e)}"
                })

    for result in results:
        print(json.dumps(result))

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python batch_runner.py CONFIG_PATH")
        sys.exit(1)
    batch_runner(sys.argv[1])
